#recipes{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:3px 12px;border-bottom:1px solid #ffffff13;font-size:11px;background:#151b16}#materialName{color:#a8b69f;white-space:nowrap}#rockControls,#agingControls{display:flex;align-items:center;gap:5px}#recipes button,#recipes select{font-size:11px;padding:3px 8px}#recipes select{max-width:105px}a{color:#d5c394}#referenceDialog p{max-width:620px;line-height:1.75}aside{font-size:12px}.layerRow input[type=number]{max-width:125px}#families button{border-color:transparent}#families button.active{border-color:#d5c39466;background:#3b382a}header nav button{border-color:transparent}#quickShapes button{border-color:transparent}#quickShapes button.active{border-color:#d5c39466}.viewbar button{background:#1a221de0;border-color:#ffffff0b}.gesture{color:#8d988d}#identity{font-size:11px}#specimenName{font-weight:500}#itemIndex{font-size:10px}#shapeName{font-size:10px}.panelHead{margin-bottom:10px}aside input[type=range]{accent-color:#d5c394}#status{pointer-events:none}#recipes button:focus-visible,button:focus-visible{outline:2px solid #d5c394;outline-offset:2px}
@media(max-width:760px){#recipes{padding:3px 7px;gap:4px;font-size:10px}#materialName{font-size:10px}#rockControls button{display:none}#recipes button{font-size:10px;padding:4px 7px}#recipes select{max-width:86px;font-size:11px}#identity{padding:2px 8px;gap:7px}header{gap:4px;padding:2px 8px}nav button{padding:3px 7px;font-size:11px}#itemIndex{font-size:9px}#recipes label{font-size:10px}.hint{max-width:96%;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
@media(max-height:450px){body{grid-template-rows:29px auto 23px 29px minmax(0,1fr) 34px}#families{grid-template-columns:repeat(7,minmax(0,1fr))}#families button{font-size:10px;padding:4px 1px}#catalog{padding:2px}#identity,#recipes{font-size:10px}footer button{padding:3px 6px}aside{top:90px;bottom:37px}.viewbar{display:flex}.viewbar #views{margin-top:0}}

@media(max-height:450px){header nav button{font-size:11px;line-height:16px;padding:2px 6px}header{padding-top:1px;padding-bottom:1px}}
